"""Reproducible, idempotent source corrections made during final audit."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def replace(rel, old, new):
    path = ROOT / rel
    text = path.read_text()
    if old not in text:
        assert new in text, (rel, old[:100])
        print(f"Already applied: {rel}: {new[:70]}")
        return
    assert text.count(old) == 1, (rel, text.count(old))
    path.write_text(text.replace(old, new))
    print(f"Applied: {rel}: {new[:70]}")

